//! Events generated by a state change are queued on the document, so they are
//! dispatched even when the change does not come from an event driver (e.g. a
//! programmatic focus change).

use blitz_dom::{Document, EventDriver, EventHandler, NodeId};
use blitz_test_harness::Harness;
use blitz_traits::events::{DomEvent, EventState};
use std::{cell::RefCell, rc::Rc};

#[derive(Clone, Default)]
struct RecordingHandler(Rc<RefCell<Vec<(NodeId, String)>>>);

impl EventHandler for RecordingHandler {
    fn handle_event(
        &mut self,
        _chain: &[NodeId],
        event: &mut DomEvent,
        _doc: &mut dyn Document,
        _event_state: &mut EventState,
    ) {
        self.0
            .borrow_mut()
            .push((event.target, event.name().to_string()));
    }
}

const HTML: &str =
    r#"<html><body><input id="a" type="text"><input id="b" type="text"></body></html>"#;

fn node_id(harness: &Harness<blitz_html::HtmlDocument>, selector: &str) -> NodeId {
    harness.base().query_selector(selector).unwrap().unwrap()
}

#[test]
fn programmatic_focus_changes_dispatch_focus_events() {
    let mut harness = Harness::from_html(HTML);
    let a = node_id(&harness, "#a");
    let b = node_id(&harness, "#b");

    let mut doc = harness.base_mut();
    doc.set_focus_to(a);
    doc.set_focus_to(b);
    doc.clear_focus();
    assert!(doc.has_pending_events());

    let handler = RecordingHandler::default();
    EventDriver::new(&mut *doc, handler.clone()).flush_pending_events();
    assert!(!doc.has_pending_events());

    let expected = [
        (a, "focus"),
        (a, "focusin"),
        (a, "blur"),
        (a, "focusout"),
        (b, "focus"),
        (b, "focusin"),
        (b, "blur"),
        (b, "focusout"),
    ]
    .map(|(id, name)| (id, name.to_string()));
    assert_eq!(*handler.0.borrow(), expected);
}

#[test]
fn queued_events_for_dropped_nodes_are_discarded() {
    let mut harness = Harness::from_html(HTML);
    let a = node_id(&harness, "#a");

    let mut doc = harness.base_mut();
    doc.set_focus_to(a);
    doc.mutate().remove_and_drop_node(a);

    let handler = RecordingHandler::default();
    EventDriver::new(&mut *doc, handler.clone()).flush_pending_events();
    assert!(handler.0.borrow().is_empty());
}

/// Focuses the other node whenever one of the two is focused
struct FocusPingPong {
    nodes: [NodeId; 2],
    focus_events: Rc<RefCell<usize>>,
}

impl EventHandler for FocusPingPong {
    fn handle_event(
        &mut self,
        _chain: &[NodeId],
        event: &mut DomEvent,
        doc: &mut dyn Document,
        _event_state: &mut EventState,
    ) {
        if event.name() == "focus" {
            *self.focus_events.borrow_mut() += 1;
            let other = self.nodes[(event.target == self.nodes[0]) as usize];
            doc.inner_mut().set_focus_to(other);
        }
    }
}

#[test]
fn flush_stops_when_handlers_keep_queueing_events() {
    let mut harness = Harness::from_html(HTML);
    let nodes = [node_id(&harness, "#a"), node_id(&harness, "#b")];

    let mut doc = harness.base_mut();
    doc.set_focus_to(nodes[0]);

    let focus_events = Rc::new(RefCell::new(0));
    let handler = FocusPingPong {
        nodes,
        focus_events: focus_events.clone(),
    };
    EventDriver::new(&mut *doc, handler).flush_pending_events();

    // The flush returned, and the events it did not get to are still queued
    assert!(*focus_events.borrow() > 1);
    assert!(doc.has_pending_events());
}
